const body = $json.body ?? $json;
const data = body.data ?? body;
const eventData = Array.isArray(data.messages) ? data.messages[0] ?? data : data;
const rootMessage = eventData.message ?? data.message ?? data;
const rootKey = eventData.key ?? data.key ?? rootMessage.key ?? {};
const mediaTypes = ['documentMessage', 'imageMessage', 'audioMessage', 'videoMessage'];
const messageTypeAliases = {
  document: 'documentMessage',
  file: 'documentMessage',
  image: 'imageMessage',
  photo: 'imageMessage',
  picture: 'imageMessage',
  audio: 'audioMessage',
  voice: 'audioMessage',
  ptt: 'audioMessage',
  video: 'videoMessage',
};

function normalizeMessageType(value) {
  if (!value) return '';
  const raw = String(value);
  return mediaTypes.includes(raw) ? raw : messageTypeAliases[raw] ?? '';
}

function inferMessageTypeFromMime(mimetype) {
  if (!mimetype) return '';
  if (mimetype.startsWith('image/')) return 'imageMessage';
  if (mimetype.startsWith('audio/')) return 'audioMessage';
  if (mimetype.startsWith('video/')) return 'videoMessage';
  if (mimetype === 'application/pdf' || mimetype.startsWith('application/')) return 'documentMessage';
  return '';
}

function looksLikeMedia(value) {
  if (!value || typeof value !== 'object') return false;
  return Boolean(
    value.mimetype ||
    value.mimeType ||
    value.url ||
    value.directPath ||
    value.mediaKey ||
    value.fileSha256 ||
    value.fileEncSha256 ||
    value.base64 ||
    value.fileName ||
    value.filename
  );
}

function findMedia(value, depth = 0, seen = new Set()) {
  if (!value || typeof value !== 'object' || depth > 8 || seen.has(value)) return null;
  seen.add(value);

  for (const type of mediaTypes) {
    if (value[type]) return { messageType: type, media: value[type] };
  }

  if (looksLikeMedia(value)) {
    const mimetype = value.mimetype ?? value.mimeType ?? '';
    return { messageType: inferMessageTypeFromMime(mimetype), media: value };
  }

  const priorityKeys = [
    'message',
    'ephemeralMessage',
    'viewOnceMessage',
    'viewOnceMessageV2',
    'viewOnceMessageV2Extension',
    'documentWithCaptionMessage',
    'editedMessage',
    'deviceSentMessage',
    'quotedMessage',
    'media',
  ];

  for (const key of priorityKeys) {
    const found = findMedia(value[key], depth + 1, seen);
    if (found) return found;
  }

  for (const nested of Object.values(value)) {
    const found = findMedia(nested, depth + 1, seen);
    if (found) return found;
  }

  return null;
}

const declaredMessageType = normalizeMessageType(eventData.messageType ?? data.messageType ?? body.messageType);
const foundMedia = findMedia(rootMessage) ?? findMedia(eventData.media) ?? findMedia(data.media) ?? findMedia(data);
const messageType = declaredMessageType || foundMedia?.messageType || '';
const media = foundMedia?.media ?? (rootMessage && typeof rootMessage === 'object' ? rootMessage[messageType] : null) ?? {};
const remoteJid = rootKey.remoteJid ?? eventData.remoteJid ?? data.remoteJid ?? '';
const normalizedRemoteJid = String(remoteJid)
  .replace('@s.whatsapp.net', '')
  .replace('@lid', '')
  .replace('@g.us', '');
const instance = body.instance ?? data.instance ?? eventData.instance ?? body.instanceName ?? data.instanceName ?? '';
const messageId = rootKey.id ?? eventData.id ?? data.id ?? media.id ?? '';
const mimetype = media.mimetype ?? media.mimeType ?? eventData.mimetype ?? data.mimetype ?? '';
const extensionByMime = {
  'application/pdf': '.pdf',
  'image/jpeg': '.jpg',
  'image/png': '.png',
  'image/webp': '.webp',
  'audio/ogg': '.ogg',
  'audio/mpeg': '.mp3',
  'audio/mp3': '.mp3',
  'audio/mp4': '.m4a',
  'audio/x-m4a': '.m4a',
  'audio/wav': '.wav',
  'video/mp4': '.mp4',
};
const extension = extensionByMime[mimetype] ?? '';
const fileName = media.fileName ?? media.filename ?? media.title ?? String(messageId || Date.now()) + (extension || '.bin');
const base64FromWebhook = media.base64 ?? eventData.base64 ?? data.base64 ?? eventData.media?.base64 ?? data.media?.base64 ?? null;
const isAcceptedMime = Boolean(mimetype && (
  mimetype.startsWith('image/') ||
  mimetype.startsWith('audio/') ||
  mimetype.startsWith('video/') ||
  mimetype === 'application/pdf' ||
  mimetype.startsWith('application/')
));
const hasFile = mediaTypes.includes(messageType) || isAcceptedMime || Boolean(media.url || media.directPath || media.mediaKey || base64FromWebhook);

return [{
  json: {
    hasFile,
    instance,
    messageId,
    remoteJid,
    normalizedRemoteJid,
    messageType,
    mimetype,
    fileName,
    base64FromWebhook,
    originalData: eventData,
  },
}];

const source = $('Normalizar mensagem').item.json;
const response = $json ?? {};
const candidates = [
  typeof response === 'string' ? response : null,
  response.base64,
  response.data,
  response.data?.base64,
  response.file?.base64,
  response.media?.base64,
  response.response?.base64,
  response.result?.base64,
  source.base64FromWebhook,
];
const rawBase64 = candidates.find((value) => typeof value === 'string' && value.trim().length > 0);

if (!rawBase64) {
  return [{
    json: {
      ...source,
      mediaReady: false,
      error_reason: response.error?.message || response.message || 'Evolution nao retornou base64 da midia',
      evolution_response: response,
    },
  }];
}

const dataUriMatch = rawBase64.match(/^data:([^;]+);base64,(.*)$/s);
const dataUriMime = dataUriMatch?.[1];
const cleanBase64 = (dataUriMatch?.[2] ?? rawBase64).replace(/s/g, '');
let buffer;
try {
  buffer = Buffer.from(cleanBase64, 'base64');
} catch (error) {
  return [{
    json: {
      ...source,
      mediaReady: false,
      error_reason: 'Base64 invalido: ' + error.message,
    },
  }];
}

if (!buffer.length) {
  return [{ json: { ...source, mediaReady: false, error_reason: 'Arquivo vazio apos conversao de base64' } }];
}

function sniff(buffer) {
  if (buffer.subarray(0, 4).toString('ascii') === '%PDF') return { mimetype: 'application/pdf', ext: '.pdf' };
  if (buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) return { mimetype: 'image/jpeg', ext: '.jpg' };
  if (buffer.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return { mimetype: 'image/png', ext: '.png' };
  if (buffer.subarray(0, 4).toString('ascii') === 'RIFF' && buffer.subarray(8, 12).toString('ascii') === 'WEBP') return { mimetype: 'image/webp', ext: '.webp' };
  if (buffer.subarray(0, 4).toString('ascii') === 'OggS') return { mimetype: 'audio/ogg', ext: '.ogg' };
  if (buffer.subarray(0, 3).toString('ascii') === 'ID3' || (buffer[0] === 0xff && [0xfb, 0xf3, 0xf2].includes(buffer[1]))) return { mimetype: 'audio/mpeg', ext: '.mp3' };
  if (buffer.subarray(0, 4).toString('ascii') === 'RIFF' && buffer.subarray(8, 12).toString('ascii') === 'WAVE') return { mimetype: 'audio/wav', ext: '.wav' };
  return { mimetype: null, ext: null };
}

function extensionForMime(mimetype) {
  return {
    'application/pdf': '.pdf',
    'image/jpeg': '.jpg',
    'image/png': '.png',
    'image/webp': '.webp',
    'audio/ogg': '.ogg',
    'audio/mpeg': '.mp3',
    'audio/mp3': '.mp3',
    'audio/mp4': '.m4a',
    'audio/x-m4a': '.m4a',
    'audio/wav': '.wav',
    'video/mp4': '.mp4',
  }[mimetype] || null;
}

function ensureExtension(fileName, ext) {
  const name = String(fileName || source.messageId || Date.now());
  if (!ext) return name.includes('.') ? name : name + '.bin';
  const currentExt = name.match(/.[a-z0-9]+$/i)?.[0]?.toLowerCase();
  if (!currentExt || currentExt === '.bin') return name.replace(/.[a-z0-9]+$/i, '') + ext;
  return name;
}

const detected = sniff(buffer);
const declaredMime = dataUriMime || response.mimetype || response.mimeType || response.data?.mimetype || source.mimetype || '';
const mimetype = (!declaredMime || declaredMime === 'application/octet-stream')
  ? (detected.mimetype || 'application/octet-stream')
  : declaredMime;
const extension = extensionForMime(mimetype) || detected.ext;
const fileName = ensureExtension(response.fileName || response.filename || response.data?.fileName || source.fileName, extension);
const binaryData = await this.helpers.prepareBinaryData(buffer, fileName, mimetype);

return [{
  json: {
    ...source,
    mediaReady: true,
    mimetype,
    fileName,
    sizeBytes: buffer.length,
  },
  binary: {
    data: binaryData,
  },
}];

const config = {
  backendUrl: 'https://virginia-backend-virginia-backend.5ivdfc.easypanel.host',
  webhookSecret: 'COLE_AQUI_VIRGINIA_WEBHOOK_SECRET',
  evolutionApiUrl: 'https://evolution-api-evolution-api.5ivdfc.easypanel.host',
  evolutionApiKey: 'COLE_AQUI_EVOLUTION_API_KEY',
  supabaseUrl: 'https://bbgjnnxstkycthuzjgsm.supabase.co',
  supabaseServiceKey: 'COLE_AQUI_SUPABASE_SERVICE_KEY',
};

return $input.all().map((item) => ({
  json: {
    ...item.json,
    __config: config,
  },
  binary: item.binary,
}));
